head.script:
scwin.userId = '';
scwin.pjtId = '';

scwin.onpageload = function () {
    scwin.userId = $p.getComponentById("mf_pg_header").getWindow().scwin.USER_ID;
    scwin.pjtId = $p.parent().scwin.SEL_PJT_ID;
    console.log('로그인한 userID : ', scwin.userId);
    console.log('현재 pjtID : ', scwin.pjtId);
    dmp_designVo.set("userId", scwin.userId);
    dmp_designVo.set("pjtId", scwin.pjtId);

    var cptIbxName = $p.getComponentById("searchComp_1");
    if (cptIbxName == undefined) {
        search_box.hide();
    }
    scwin.handleWbsParam();
    scwin.btn_search_onclick();
};

scwin.btn_search_onclick = function (e) {
    dmp_designVo.set("pageIndex", "1");
    pgl_designList.setSelectedIndex(1);
    $c.sbm.execute($p, sbm_selectDesignVoList);
};

scwin.sbm_designList_submitdone = function (e) {
    scwin.globalElData = e.responseJSON.elData;
    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    console.log("조회된 데이터 :", elData);

    if (elHeader == null || elHeader == "" || elHeader == "undefiend" || elHeader.resSuc == false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    dlt_designVoList.setJSON(elData.designVoList);
    spn_listCnt.setLabel(elData.totalCount);

    var totalPageCount = Math.ceil(elData.totalCount / dmp_designVo.get("pageSize"));
    pgl_designList.setCount(totalPageCount);
    spn_totalPageCount.setValue(totalPageCount);
    spn_pageIndex.setValue(dmp_designVo.get("pageIndex"));
    pgl_designList.setSelectedIndex(dmp_designVo.get("pageIndex"));

    // 스타일 적용
    setTimeout(function() {
        scwin.setProgressStyle();
        scwin.setTaskStatusStyle();
    }, 100);
};

scwin.pgl_designList_onclick = function (idx) {
    dmp_designVo.set("pageIndex", idx);
    $c.sbm.execute($p, sbm_selectDesignVoList);
};

scwin.btn_reset_onclick = function (e) {
    dmp_designVo.setEmptyValue();
    dmp_designVo.set("pageIndex", "1");
    pgl_designList.setSelectedIndex(1);
    dmp_designVo.set("userId", scwin.userId);
    dmp_designVo.set("pjtId", scwin.pjtId);
    $c.sbm.execute($p, sbm_selectDesignVoList);
};

scwin.btn_add_onclick = function (e) {
    dlt_designVoList.insertRow(0);
};

scwin.btn_delete_onclick = function (e) {
    let chkArrIdx = grd_list.getCheckedIndex("chk");
    dlt_designVoList.deleteRows(chkArrIdx);
};

scwin.btn_save_onclick = function (e) {
    let modifiedData = dlt_designVoList.getModifiedJSON();

    modifiedData.forEach(function (item) {
        item.userId = scwin.userId;
        item.pjtId = scwin.pjtId;
        item.isDesign = 1; // 설계업무로 설정
    });

    let reqObj = {
        "elData": {
            "designVoList": modifiedData
        }
    };
    $c.sbm.execute($p, sbm_saveDesignVoList, reqObj);
};

scwin.sbm_saveDesignVoList_submitdone = function (e) {
    var elHeader = e.responseJSON.elHeader;
    if (elHeader == null || elHeader == "" || elHeader == "undefiend" || elHeader.resSuc == false) {
        $c.win.alert($p, `에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    } else {
        scwin.showToast("저장되었습니다.");
    }
    scwin.btn_search_onclick();
};

scwin.grd_list_oncellclick = function (row, col, colId) {
    if (colId === "ptTaskName") {
        scwin.openParentTaskPopup(row);
    }
    if (colId === "taskId") { // 설계업무ID 클릭시, 해당 설계업무ID를 부모로 가지는 개발 업무 목록 페이지로 이동.
        var selectedRow = dlt_designVoList.getRowJSON(row)

        var tab_content = $p.parent().tab_content;
        var tabId = "tab_1";
        var title = "개발 업무";
        var url = "task/develop/DevelopList.xml";

        var rowJSON = {
        "deTaskId" : selectedRow.taskId
        };  

        // 새 탭 생성
        tab_content.addTab(tabId, {
            "label": title,
            "closable": "true",
            "openAction": "exist",
        }, {
            "src": url,
            "frameMode": "wframe",
            "dataObject":{
                "type" : "json",
                "name" : "tabParam",
                "data" : rowJSON
            }
        });

        tab_content.setSelectedTabIndex(tabId);

    };

};

scwin.openDetailPopup = function (rowIndex) {
    let rowData = dlt_designVoList.getRowJSON(rowIndex);

    var jsnPopupData = {
        "type": "json",
        "name": "taskData",
        "data": rowData
    };

    var options = {
        id: "task_detail_popup",
        type: "wframePopup",
        width: "750px",
        height: "700px",
        top: "30px",
        left: "200px",
        popupName: "업무 상세 정보",
        modal: true,
        closeAction: "scwin.detailPopup_closeAction",
        dataObject: jsnPopupData
    };

    $p.openPopup("/InsWebApp/ui/task/design/DesignPopup.xml", options);
};

scwin.openParentTaskPopup = function (rowIndex) {
    let rowData = dlt_designVoList.getRowJSON(rowIndex);

    var taskData = {
        currentTaskId: rowData.taskId,
        currentTaskName: rowData.taskName,
        currentRowIndex: rowIndex,
        currentPjtId: scwin.pjtId
    };

    var jsnPopupData = {
        "type": "json",
        "name": "taskData",
        "data": taskData
    };

    var options = {
        id: "task_tree_popup",
        type: "wframePopup",
        width: "600px",
        height: "650px",
        top: "30px",
        left: "300px",
        popupName: "업무 트리 선택",
        modal: true,
        closeAction: "scwin.taskTreePopup_closeAction",
        dataObject: jsnPopupData
    };

    $p.openPopup("/InsWebApp/ui/task/design/DesignTaskTree.xml", options);
};

// TaskTree.xml (상위 업무 선택을 위한 업무 트리) 팝업에서 받아온 데이터
scwin.receiveTaskData = function (returnData) {
    if (returnData && returnData.selectedTask) {
        var selectedTask = returnData.selectedTask;
        var currentRowIndex = returnData.currentRowIndex;

        if (currentRowIndex !== null && currentRowIndex >= 0) {
            dlt_designVoList.setCellData(currentRowIndex, "ptTaskId", selectedTask.taskId);
            dlt_designVoList.setCellData(currentRowIndex, "ptTaskName", selectedTask.taskName);
            dlt_designVoList.setCellData(currentRowIndex, "taskDepth", parseInt(selectedTask.taskDepth) + 1);

            console.log(`상위업무 선택 완료: [${selectedTask.taskName}] (원본 depth: ${selectedTask.taskDepth}, 설정될 depth: ${parseInt(selectedTask.taskDepth) + 1})`);
            scwin.showToast("선택된 업무: " + selectedTask.taskName);
        }
    }
};

// ================================================================
// 스타일 적용 함수들
// ================================================================

/**
 * 진척률별 프로그래스 바 스타일 적용
 * @description 진척률에 따라 그리드 셀에 프로그래스 바 스타일을 적용합니다.
 */
scwin.setProgressStyle = function () {
    const rowCount = dlt_designVoList.getRowCount();
    const colIndex = grd_list.getColumnIndex("taskRate");

    for (let i = 0; i < rowCount; i++) {
        const percent = parseInt(dlt_designVoList.getCellData(i, "taskRate"), 10) || 0;

        let styleValue = "#f8f9fa";
        if (percent > 0) {
            styleValue = `linear-gradient(to right,
                #EC9192 0%,
                #EC9192 ${percent}%,
                #f8f9fa ${percent}%,
                #f8f9fa 100%)`;
        }

        // 진척률에 따른 글자 색상 결정
        let textColor = "#333333";
        if (percent > 50) {
            textColor = "#ffffff";
        }

        const styles = [
            { type: "cell", rowIndex: i, colIndex, styleName: "background", styleValue },
            { type: "cell", rowIndex: i, colIndex, styleName: "border-radius", styleValue: "12px" },
            { type: "cell", rowIndex: i, colIndex, styleName: "text-align", styleValue: "center" },
            { type: "cell", rowIndex: i, colIndex, styleName: "color", styleValue: textColor },
            { type: "cell", rowIndex: i, colIndex, styleName: "font-weight", styleValue: "bold" },
        ];

        styles.forEach(style => grd_list.setStyleAll(style));
    }
};

/**
 * 업무상태별 스타일 적용 (배지 스타일)
 * @description 업무상태에 따라 배지 형태로 스타일을 적용합니다.
 */
scwin.setTaskStatusStyle = function () {
    const rowCount = dlt_designVoList.getTotalRow();
    const colIndex = grd_list.getColumnIndex("taskStatus");

    for (let i = 0; i < rowCount; i++) {
        const status = dlt_designVoList.getCellData(i, "taskStatus");
        let backgroundColor = "#f8f9fa";
        let textColor = "#333333";

        switch (status) {
            case "대기":
                backgroundColor = "#FFF3CD";
                textColor = "#333";
                break;
            case "진행중":
                backgroundColor = "#CCE7F0";
                textColor = "#333";
                break;
            case "완료":
                backgroundColor = "#D4EDDA";
                textColor = "#333";
                break;
        }

        const styles = [
            { type: "cell", rowIndex: i, colIndex, styleName: "background-color", styleValue: backgroundColor },
            { type: "cell", rowIndex: i, colIndex, styleName: "color", styleValue: textColor },
            { type: "cell", rowIndex: i, colIndex, styleName: "border-radius", styleValue: "20px" },
            { type: "cell", rowIndex: i, colIndex, styleName: "text-align", styleValue: "center" },
            { type: "cell", rowIndex: i, colIndex, styleName: "font-weight", styleValue: "bold" },
            { type: "cell", rowIndex: i, colIndex, styleName: "font-size", styleValue: "11px" },
            { type: "cell", rowIndex: i, colIndex, styleName: "border", styleValue: "none" }
        ];

        styles.forEach(style => grd_list.setStyleAll(style));
    }
};

// 엑셀 다운로드
scwin.btn_excel_download_onclick = function (e) {
    // 전체 건수 확인
    var totalCount = scwin.globalElData ? scwin.globalElData.totalCount : 0;
    console.log("전체 데이터 건수:", totalCount);
    console.log("globalElData:", scwin.globalElData);

    if (totalCount === 0) {
        scwin.showToast("다운로드할 데이터가 없습니다.","info");
        return;
    }

    // 현재 페이징 조건 백업
    var originalPageIndex = dmp_designVo.get("pageIndex");
    var originalPageSize = dmp_designVo.get("pageSize");

    // 전체 데이터 조회를 위한 조건 설정
    dmp_designVo.set("pageIndex", "1");
    dmp_designVo.set("pageSize", totalCount.toString()); // 전체 건수만큼 설정

    // 전체 데이터 조회 실행
    $c.sbm.execute($p, sbm_selectDesignVoListForExcel);

    // 원래 페이징 조건 복원
    dmp_designVo.set("pageIndex", originalPageIndex);
    dmp_designVo.set("pageSize", originalPageSize);
};

// 엑셀 다운로드용 전체 데이터 조회 완료 후 처리
scwin.sbm_selectDesignVoListForExcel_submitdone = function (e) {
    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    if (elHeader == null || elHeader == "" || elHeader == "undefined" || elHeader.resSuc == false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    // 전체 데이터가 없는 경우
    if (!elData.designVoList || elData.designVoList.length === 0) {
        scwin.showToast("다운로드할 데이터가 없습니다.","info");
        return;
    }

    console.log("엑셀 다운로드 실제 조회된 데이터 건수:", elData.designVoList.length);

    // 임시로 그리드에 전체 데이터 설정
    var originalData = dlt_designVoList.getAllJSON();
    dlt_designVoList.setJSON(elData.designVoList);

    // 엑셀 다운로드 실행
    var options = {
        fileName: "설계_업무_목록_" + new Date().toISOString().slice(0, 10).replace(/-/g, ""),
        // useStyle 및 headerFontBold 설정을 이용하여 GridView를 Excel 파일로 다운로드할 때 헤더 폰트를 굵게 표시
        useStyle: true,
        headerFontBold: true,
        bodyFontBold: false,
        type: 1, // inputType이 "select", "autoComplete", 혹은 "checkcombobox"인 경우 >> label 값 다운
        trim: 1,
        removeColumns: "0", // 체크박스는 다운로드 안함.
        processMsg: "엑셀 파일을 생성하고 있습니다...",
        timeout: 60000,
        checkInterval: 1000,
        onSuccessCallback: function () {
            scwin.showToast("엑셀 파일 다운로드가 완료되었습니다.");
            // 원래 데이터로 복원
            dlt_designVoList.setJSON(originalData);
        },
        onFailureCallback: function () {
            scwin.showToast("엑셀 파일 다운로드에 실패했습니다.","warning");
            // 원래 데이터로 복원
            dlt_designVoList.setJSON(originalData);
        }
    };

    grd_list.advancedExcelDownload(options);
};

scwin.taskTreePopup_closeAction = function () {
    return true;
};

scwin.detailPopup_closeAction = function () {
    return true;
};

scwin.grd_list_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    scwin.openDetailPopup(rowIndex);
};

// 엑셀 업로드
scwin.btn_excel_upload_onclick = function (e) {
    console.log("=== 엑셀 업로드 시작 ===");

    var options = {
        headerExist: "1",              // 첫 번째 행을 헤더로 사용
        type: "1",                     // label 값으로 업로드 (select 컬럼의 표시값 사용)
        trim: "1",                     // 공백 제거
        status: "C",                   // 업로드된 데이터를 신규 추가 상태로 설정
        readUntilEmptyRow: "1",        // 빈 행 만나면 읽기 중단
        dateFormat: "yyyy-MM-dd",      // inputType이 캘린더인 컬럼 형식 지정
        append: "0",                   // 기존 데이터 삭제 후 새 데이터 추가 (이 옵션이 removeAll() 역할)
        frameModal: true,
        processMsg: "엑셀 파일을 업로드하고 있습니다..."
    };

    grd_list.advancedExcelUpload(options);

    console.log("업로드 이후 데이터리스트 : ", dlt_designVoList);
};

/**
 * 엑셀 업로드 템플릿 다운로드
 * 사용자가 쉽게 엑셀을 작성할 수 있도록 샘플 데이터와 가이드가 포함된 템플릿 제공
 */
scwin.btn_excel_template_download_onclick = function (e) {
    console.log("=== 엑셀 템플릿 다운로드 시작 ===");

    // 기존 데이터 백업
    var originalData = dlt_designVoList.getAllJSON();

     // 샘플 데이터와 가이드 생성
    var sampleData = [
        {
            taskName: "=== 업무명 작성 가이드 ===",
            ptTaskName: "=== 상위업무명 입력 (정확한 업무명 입력) ===",
            taskStatus: "대기",
            taskSt: "2025-01-15",
            taskEt: "2025-01-20",
            taskAsi: "담당자명",
            taskRate: "0"
        },
        {
            taskName: "메인페이지 기획",
            ptTaskName: "",
            taskStatus: "대기",
            taskSt: "2025-01-15",
            taskEt: "2025-01-20",
            taskAsi: "기획자",
            taskRate: "0"
        },
        {
            taskName: "메인페이지 와이어프레임",
            ptTaskName: "메인페이지 기획",
            taskStatus: "대기",
            taskSt: "2025-01-21",
            taskEt: "2025-01-25",
            taskAsi: "기획자",
            taskRate: "0"
        },
        {
            taskName: "메인페이지 상세설계",
            ptTaskName: "메인페이지 기획",
            taskStatus: "대기",
            taskSt: "2025-01-26",
            taskEt: "2025-01-30",
            taskAsi: "디자이너",
            taskRate: "0"
        },
        {
            taskName: "사용자 관리",
            ptTaskName: "",
            taskStatus: "대기",
            taskSt: "2025-02-01",
            taskEt: "2025-02-05",
            taskAsi: "개발자",
            taskRate: "0"
        },
        {
            taskName: "로그인 기능",
            ptTaskName: "사용자 관리",
            taskStatus: "대기",
            taskSt: "2025-02-06",
            taskEt: "2025-02-10",
            taskAsi: "개발자",
            taskRate: "0"
        }
    ];

    // 임시로 샘플 데이터 설정
    dlt_designVoList.setJSON(sampleData);

    // 엑셀 다운로드 실행
    var options = {
        fileName: "설계업무_업로드_템플릿_" + new Date().toISOString().slice(0, 10).replace(/-/g, ""),
        useStyle: true,
        headerFontBold: true,
        bodyFontBold: false,
        type: 1,
        trim: 1,
        removeColumns: "10, 11", // 진척률 , 프로젝트ID 컬럼 제외
        processMsg: "템플릿 파일을 생성하고 있습니다...",
        timeout: 60000,
        checkInterval: 1000,
        onSuccessCallback: function () {
