scwin.handleWbsParam = function() {
    try {
        var wbsData = $p.getParameter("tabData");
        if (wbsData && wbsData.fromWbs && wbsData.selectedTaskId) {
            dmp_designVo.set("scTaskId", wbsData.selectedTaskId);
            console.log("WBS에서 전달받은 업무ID:", wbsData.selectedTaskId);
        }
    } catch (e) {
        console.log("WBS 파라미터 처리 생략");
    }
};

// 전역 토스트 함수 호출 헬퍼
scwin.showToast = function (message, type = 'success', duration = 3000) {
    // 메인 페이지의 전역 토스트 함수 호출
    try {
        if ($p.top() && $p.top().scwin && $p.top().scwin.showGlobalToast) {
            $p.top().scwin.showGlobalToast(message, type, duration);
        } else {
            // 전역 함수를 찾을 수 없는 경우 기본 alert 사용
            $c.win.alert(message);
        }
    } catch (e) {
        console.error("토스트 표시 중 오류:", e);
        $c.win.alert(message);
    }
};
